# owner: platform
"""Snap spans to a fixed step and label them for payroll."""

from typing import Iterable, List, Tuple

from hourglass.models import Span
from hourglass.parsing import format_clock

# ---
def round_spans(
    spans: Iterable[Span], step_minutes: int
) -> List[str]:
    """Snap spans to the nearest step. Halves round up."""
    _check_step(step_minutes)
    return [_label(span, step_minutes) for span in spans]

def _check_step(step_minutes: int) -> None:
    is_int = isinstance(step_minutes, int)
    if not is_int or step_minutes <= 0 or 60 % step_minutes:
        raise ValueError(
            f"step must divide 60: {step_minutes!r}"
        )

def _label(span: Span, step_minutes: int) -> str:
    start, end = _snap_span(span, step_minutes)
    hours, mins = divmod(end - start, 60)
    times = f"{format_clock(start)}-{format_clock(end)}"
    return f"{times} ({hours}h {mins}m)"

def _snap_span(
    span: Span, step_minutes: int
) -> Tuple[int, int]:
    start = _snap(span.start, step_minutes)
    end = _snap(span.end, step_minutes)
    if end <= start:
        raise ValueError(f"span rounds to nothing: {span}")
    return start, end

def _snap(minutes: int, step_minutes: int) -> int:
    half = step_minutes // 2
    return (minutes + half) // step_minutes * step_minutes
